<script setup lang="ts">
import MailSource from './MailSource.vue';
import {reactive,ref} from 'vue';import type {Task} from '../types';import {formFromTemporal,temporalFromForm,kindNames,displayTime,changedFields,statusNames} from '../domain';import {request,errorText} from '../api';
const props=defineProps<{task?:Task}>();const emit=defineEmits<{saved:[];cancel:[]}>();
const initial={title:props.task?.title??'',kind:props.task?.kind??'custom',priority:props.task?.priority??2,notes:props.task?.notes??'',...formFromTemporal(props.task?.temporal)};
const end=props.task?.temporal?.ends_at?formFromTemporal({...props.task.temporal,starts_at:props.task.temporal.ends_at}):{date:'',time:''};
const fields=reactive({...initial,endDate:end.date,endTime:end.time});const error=ref(''),busy=ref(false);
async function save(){busy.value=true;error.value='';try{
 const basic={title:fields.title.trim(),kind:fields.kind,priority:Number(fields.priority),notes:fields.notes};if(!basic.title)throw new Error('请填写待办名称');
 const changes:Record<string,unknown>=props.task?changedFields({title:initial.title,kind:initial.kind,priority:initial.priority,notes:initial.notes},basic):basic;
 const timeChanged=['date','time','timezone','kind'].some(key=>(fields as any)[key] !== (initial as any)[key])||fields.endDate!==end.date||fields.endTime!==end.time;
 if(!props.task||timeChanged){const temporal=temporalFromForm(fields.date,fields.time,fields.kind,fields.timezone);if(fields.endTime&&fields.endDate)temporal.ends_at=temporalFromForm(fields.endDate,fields.endTime,'interview',fields.timezone).starts_at;
  if(props.task&&!confirm(`原时间：${displayTime(props.task.starts_at??props.task.due_at)}\n新时间：${fields.date} ${fields.time||'具体时刻待确认'} (${fields.timezone})\n保存后旧提醒将失效并按新时间安排。是否继续？`))return;changes.temporal=temporal;}
 if(props.task)await request(`/tasks/${props.task.id}`,'PATCH',{expected_version:props.task.version,changes});else await request('/tasks','POST',changes);emit('saved');
 }catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function start(){if(!props.task)return;busy.value=true;try{await request(`/tasks/${props.task.id}`,'PATCH',{expected_version:props.task.version,changes:{status:'in_progress'}});emit('saved');}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function snooze(r:any){busy.value=true;try{await request(`/reminders/${r.id}/snooze`,'POST',{expected_version:r.version,minutes:10});emit('saved');}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
</script>
<template><form @submit.prevent="save"><div class="form-body"><label>要做什么<input v-model="fields.title" placeholder="例如：准备面试项目复盘" maxlength="200" required autofocus/></label><div class="form-row"><label>事项类型<select v-model="fields.kind"><option v-for="(label,key) in kindNames" :value="key">{{label}}</option></select></label><label>优先级<select v-model="fields.priority"><option :value="1">高优先级</option><option :value="2">普通优先级</option><option :value="3">低优先级</option></select></label></div><div class="field-section"><div class="field-heading">{{['interview','written_exam'].includes(fields.kind)?'开始时间':'截止时间'}} <span>可以稍后确定</span></div><div class="form-row"><label>日期<input v-model="fields.date" type="date"/></label><label>具体时间<input v-model="fields.time" type="time" :disabled="!fields.date"/></label></div><div v-if="['interview','written_exam'].includes(fields.kind)" class="form-row"><label>结束日期（可选）<input v-model="fields.endDate" type="date"/></label><label>结束时间（可选）<input v-model="fields.endTime" type="time" :disabled="!fields.endDate"/></label></div><label>时间所在时区<select v-model="fields.timezone"><option value="Asia/Shanghai">北京时间 · Asia/Shanghai</option><option value="Asia/Tokyo">东京时间 · Asia/Tokyo</option><option value="UTC">协调世界时 · UTC</option><option value="Europe/London">伦敦时间 · Europe/London</option><option value="America/New_York">纽约时间 · America/New_York</option></select></label><p class="field-help">{{fields.date&&!fields.time?'只保存日期，具体时刻确认后才安排定时提醒。':'提醒按事项类型安排；仅改标题会保留原始时间依据。'}}</p></div><label>备注<textarea v-model="fields.notes" rows="3" maxlength="4000" placeholder="需要准备的材料、想提醒自己的事…"/></label><button v-if="task?.status==='pending'" type="button" class="button" :disabled="busy" @click="start">标记为进行中</button><div v-if="task?.next_reminder_at" class="subtle-box">下一次提醒：{{displayTime(task.next_reminder_at)}}</div><details v-if="task?.reminders?.length"><summary>提醒计划与历史</summary><div v-for="r in task.reminders" class="notice"><p>{{displayTime(String(r.fire_at))}} · {{statusNames[String(r.state)]??r.state}}</p><button v-if="['pending','retry_wait'].includes(String(r.state))" type="button" class="text-button" :disabled="busy" @click="snooze(r)">仅延后此提醒 10 分钟</button></div></details><MailSource v-if="task?.source" :source="task.source"/><p v-if="error" class="error-box" role="alert">{{error}}<span v-if="error.includes('版本')||error.includes('其他')"> 请关闭并重新打开此事项，核对最新内容后再修改；本次编辑没有覆盖服务器数据。</span></p></div><footer class="modal-actions"><button type="button" class="button" @click="emit('cancel')">取消</button><button class="button primary" :disabled="busy">{{busy?'正在保存…':task?'保存修改':'添加待办'}}</button></footer></form></template>
